import api from '../../services/api';

const LOGO = "data:image/png;base64,";

const DATA = {
  mr: {
    clinicName: "'श्रे' यश श्री क्लिनिक",
    doc1: { name: "डॉ. संस्कृती वळसंगकर", deg: "B.A.M.S.", spec: "फॅमिली फिजिशियन व स्त्रीरोगतज्ञ", reg: "रजि. नं. I-84383-A-1", mob: "मो.: 8446673272 | W.A.: 8380851996" },
    doc2: { name: "डॉ. श्रेयस वळसंगकर", deg: "B.A.M.S.CCH, CGO.", spec: "फॅमिली फिजिशियन व सर्जन", reg: "रजि. नं. I-65823-A-1", mob: "मो.: 9665456099 | W.A.: 7620111866" },
    addr: "★ कन्सल्टींग १ – सी-१७५/१७६, गंगासागर, श्रीकांत नगर, मोनार्क हॉस्पिटल समोर, जुले सोलापूर. | वेळ: सकाळी १०–२ | सायं. ६–१०",
    addr2: "★ कन्सल्टींग २ – प्लॉट नं. ९, यश नगर, रेणुका मंगल कार्यालयजवळ, जुले सोलापूर. | वेळ: सकाळी ८–१० | सायं. ७–९",
    L: { date: "दिनांक", visit: "भेट ID", pname: "रुग्णाचे नाव", age: "वय / लिंग", pid: "रुग्ण ID", meds: "औषधे", no: "क्र.", med: "औषध", dose: "मात्रा", freq: "वेळा", dur: "कालावधी", instr: "सूचना", fu: "पुढील भेट", valid: "हे प्रिस्क्रिप्शन जारी केल्याच्या तारखेपासून ३० दिवस वैध आहे.", empty: "कोणतीही औषधे लिहून दिली नाहीत" },
  },
  hi: {
    clinicName: "'श्रे' यश श्री क्लिनिक",
    doc1: { name: "डॉ. संस्कृती वळसंगकर", deg: "B.A.M.S.", spec: "फैमिली फिजिशियन व स्त्री रोग विशेषज्ञ", reg: "रजि. नं. I-84383-A-1", mob: "मो.: 8446673272 | W.A.: 8380851996" },
    doc2: { name: "डॉ. श्रेयस वळसंगकर", deg: "B.A.M.S.CCH, CGO.", spec: "फैमिली फिजिशियन व सर्जन", reg: "रजि. नं. I-65823-A-1", mob: "मो.: 9665456099 | W.A.: 7620111866" },
    addr: "★ परामर्श १ – C-175/176, गंगासागर, श्रीकांत नगर, मोनार्क हॉस्पिटल के सामने, जुले सोलापुर. | समय: सुबह १०–२ | शाम ६–१०",
    addr2: "★ परामर्श २ – प्लॉट नं. 9, यश नगर, रेणुका मंगल कार्यालय के पास, जुले सोलापुर. | समय: सुबह ८–१० | शाम ७–९",
    L: { date: "दिनांक", visit: "विज़िट ID", pname: "रोगी का नाम", age: "आयु / लिंग", pid: "रोगी ID", meds: "दवाइयाँ", no: "क्र.", med: "दवा", dose: "मात्रा", freq: "बार", dur: "अवधि", instr: "निर्देश", fu: "अगली मुलाकात", valid: "यह नुस्खा जारी तिथि से ३० दिन तक मान्य है।", empty: "कोई दवाई नहीं लिखी गई" },
  },
  en: {
    clinicName: "'Shre' Yash Shri Clinic",
    doc1: { name: "Dr. Sanskruti Valsangkar", deg: "B.A.M.S.", spec: "Family Physician & Gynaecologist", reg: "Reg. No: I-84383-A-1", mob: "Mob: 8446673272 | W.A.: 8380851996" },
    doc2: { name: "Dr. Shreyas Valsangkar", deg: "B.A.M.S.CCH, CGO.", spec: "Family Physician & Surgeon", reg: "Reg. No: I-65823-A-1", mob: "Mob: 9665456099 | W.A.: 7620111866" },
    addr: "★ Consulting 1 – C-175/176, Gangasagar, Shrikant Nagar, Near Monarch Hospital, Julle Solapur. | Timing: 10AM–2PM | 6PM–10PM",
    addr2: "★ Consulting 2 – Plot No. 9, Yash Nagar, Near Renuka Mangal Karyalay, Julle Solapur. | Timing: 8AM–10AM | 7PM–9PM",
    L: { date: "Date", visit: "Visit ID", pname: "Patient Name", age: "Age / Gender", pid: "Patient ID", meds: "Medicines Prescribed", no: "#", med: "Medicine", dose: "Dosage", freq: "Frequency", dur: "Duration", instr: "Instructions", fu: "Follow-up", valid: "This prescription is valid for 30 days from date of issue.", empty: "No medicines prescribed" },
  }
};

export default function PrescriptionPrint() {
  const { visitId } = useParams();
  const [lang, setLang] = useState('mr');
  const [size, setSize] = useState('a4');
  const [visit, setVisit] = useState(null);
  const [prescriptions, setPrescriptions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    async function loadData() {
      try {
        const [visitRes, rxRes] = await Promise.all([
          api.get(`/visits/${visitId}`),
          api.get(`/prescriptions/visit/${visitId}`),
        ]);
        setVisit(visitRes.data?.data ?? visitRes.data);
        const rx = rxRes.data?.data ?? rxRes.data;
        setPrescriptions(Array.isArray(rx) ? rx : []);
      } catch (err) {
        setError(err.response?.data?.message || 'Failed to load prescription data.');
      } finally {
        setLoading(false);
      }
    }
    loadData();
  }, [visitId]);

  const dynamicData = useMemo(() => {
    if (!visit) return null;
    const pt = visit.patient || {};
    const doc = visit.doctor || {};
    return {
      date: visit.visitDate ? new Date(visit.visitDate).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }) : '—',
      visitId: `V-${visit.id.slice(0, 8).toUpperCase()}`,
      pt: {
        name: `${pt.firstName || ''} ${pt.lastName || ''}`.trim() || '—',
        age: pt.dateOfBirth
          ? `${new Date().getFullYear() - new Date(pt.dateOfBirth).getFullYear()} yrs / ${pt.gender === 'MALE' ? 'M' : pt.gender === 'FEMALE' ? 'F' : 'O'}`
          : `— / ${pt.gender || '—'}`,
        id: `PT-${pt.id.slice(0, 5).toUpperCase()}`
      },
      fuDate: visit.followUpDate ? new Date(visit.followUpDate).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }) : '—',
      sigName: `Dr. ${doc.firstName || ''} ${doc.lastName || ''}`,
      sigReg: doc.qualification || doc.specialization || 'Physician',
      meds: prescriptions.map(p => ({
        n: p.medicine?.name || p.customMedicineName || '—',
        g: p.medicine?.brandName || p.medicine?.manufacturer || '',
        d: p.dosage || '—',
        f: p.frequency || '—',
        dur: p.duration || '—',
        i: p.instructions || '—'
      }))
    };
  }, [visit, prescriptions]);

  if (loading) return <div style={{ padding: 20 }}>Loading prescription...</div>;
  if (error) return <div style={{ padding: 20, color: 'red' }}>Error: {error}</div>;
  if (!visit) return <div style={{ padding: 20 }}>Visit not found.</div>;

  const d = DATA[lang];
  const L = d.L;
  const isA5 = size === 'a5';

  return (
    <div style={{ background: '#f5f5f5', minHeight: '100vh', padding: 20, fontFamily: 'Arial, sans-serif' }}>
      <style>{`
        * { box-sizing: border-box; margin: 0; padding: 0; }
        .controls { max-width: 720px; margin: 0 auto 12px; display: flex; gap: 0; flex-wrap: wrap; }
        .top-bar { display: flex; gap: 0; max-width: 720px; margin: 0 auto 0; }
        .tab { flex: 1; padding: 8px 0; text-align: center; font-size: 13px; font-weight: 500; cursor: pointer; border: 1px solid #ccc; background: #f9f9f9; color: #555; transition: all .15s; }
        .tab:first-child { border-radius: 8px 0 0 8px; }
        .tab:last-child { border-radius: 0 8px 8px 0; }
        .tab.active { background: #7a1a2e; color: #fff; border-color: #7a1a2e; }
        .bar2 { display: flex; gap: 8px; max-width: 720px; margin: 8px auto 12px; align-items: center; }
        .sbtn { font-size: 12px; padding: 6px 16px; border-radius: 6px; border: 1px solid #ccc; background: #f9f9f9; color: #555; cursor: pointer; }
        .sbtn.active { background: #7a1a2e; color: #fff; border-color: #7a1a2e; }
        .pbtn { font-size: 12px; padding: 6px 16px; border-radius: 6px; border: 1px solid #7a1a2e; background: #7a1a2e; color: #fff; cursor: pointer; margin-left: auto; }

        /* prescription */
        .rx { background: #fff; color: #1a1a1a; font-family: Arial, sans-serif; margin: 0 auto; }
        .rx.a4 { max-width: 700px; padding: 30px 36px; border: 1px solid #ccc; box-shadow: 0 2px 12px rgba(0,0,0,.12); }
        .rx.a5 { max-width: 480px; padding: 18px 22px; border: 1px solid #ccc; box-shadow: 0 2px 12px rgba(0,0,0,.12); }

        /* header */
        .hd { border-bottom: 2.5px solid #7a1a2e; padding-bottom: 10px; margin-bottom: 12px; }
        .clinic-row { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; }
        .clinic-title { font-weight: 700; color: #7a1a2e; text-align: center; flex: 1; }
        .a4 .clinic-title { font-size: 22px; }
        .a5 .clinic-title { font-size: 16px; }
        .logo-wrap { display: flex; justify-content: center; align-items: center; }
        .a4 .logo-wrap img { height: 70px; width: auto; }
        .a5 .logo-wrap img { height: 48px; width: auto; }
        .doctors-row { display: grid; grid-template-columns: 1fr auto 1fr; gap: 0; align-items: start; }
        .doc-l { text-align: left; } .doc-r { text-align: right; } .doc-c { display: flex; align-items: center; justify-content: center; padding: 0 8px; }
        .doc-name { font-weight: 700; color: #7a1a2e; }
        .doc-deg { color: #5a1a28; }
        .doc-spec { color: #5a1a28; font-style: italic; }
        .doc-meta { color: #6b7280; }
        .a4 .doc-name { font-size: 14px; } .a4 .doc-deg { font-size: 12px; margin-top: 1px; } .a4 .doc-spec { font-size: 11px; margin-top: 1px; } .a4 .doc-meta { font-size: 11px; margin-top: 1px; }
        .a5 .doc-name { font-size: 11px; } .a5 .doc-deg { font-size: 9px; margin-top: 1px; } .a5 .doc-spec { font-size: 9px; margin-top: 1px; } .a5 .doc-meta { font-size: 9px; margin-top: 1px; }
        .addr-bar { text-align: center; color: #5a1a28; border-top: 1px solid #e5c0c8; margin-top: 8px; padding-top: 6px; }
        .a4 .addr-bar { font-size: 10px; line-height: 1.6; } .a5 .addr-bar { font-size: 8px; line-height: 1.5; }

        /* rx meta */
        .rx-meta { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; }
        .rx-sym { font-weight: 700; color: #7a1a2e; line-height: 1; }
        .a4 .rx-sym { font-size: 32px; } .a5 .rx-sym { font-size: 22px; }
        .rx-date { text-align: right; color: #6b7280; }
        .a4 .rx-date { font-size: 11px; } .a5 .rx-date { font-size: 9px; }

        /* patient bar */
        .pt-bar { background: #fdf2f4; border-radius: 5px; display: grid; grid-template-columns: 1fr 1fr 1fr; border: 1px solid #f0d0d6; margin-bottom: 10px; }
        .a4 .pt-bar { padding: 8px 12px; gap: 8px; } .a5 .pt-bar { padding: 5px 8px; gap: 5px; }
        .pt-f label { display: block; text-transform: uppercase; letter-spacing: .04em; color: #9ca3af; }
        .pt-f span { font-weight: 600; color: #1a1a1a; }
        .a4 .pt-f label { font-size: 9px; } .a4 .pt-f span { font-size: 12px; }
        .a5 .pt-f label { font-size: 8px; } .a5 .pt-f span { font-size: 10px; }

        /* section label */
        .sec-lbl { font-weight: 700; color: #7a1a2e; text-transform: uppercase; letter-spacing: .06em; border-bottom: 1px solid #e5c0c8; padding-bottom: 3px; }
        .a4 .sec-lbl { font-size: 10px; margin: 10px 0 6px; } .a5 .sec-lbl { font-size: 9px; margin: 7px 0 4px; }

        /* table */
        .rx table { width: 100%; border-collapse: collapse; }
        .rx table thead tr { background: #7a1a2e; }
        .rx table thead th { color: #fff; text-align: left; font-weight: 600; }
        .a4 table thead th { padding: 7px 9px; font-size: 11px; }
        .a5 table thead th { padding: 5px 6px; font-size: 9px; }
        .rx table tbody tr { border-bottom: 1px solid #f0d0d6; }
        .rx table tbody tr:nth-child(even) { background: #fdf8f8; }
        .rx table td { color: #1a1a1a; vertical-align: top; }
        .a4 table td { padding: 8px 9px; font-size: 12px; }
        .a5 table td { padding: 5px 6px; font-size: 10px; }
        .mn { font-weight: 600; }
        .mg { color: #9b6b72; }
        .a4 .mg { font-size: 10px; margin-top: 1px; } .a5 .mg { font-size: 8px; }

        /* footer */
        .ft { display: flex; justify-content: space-between; align-items: flex-end; border-top: 1.5px solid #e5c0c8; }
        .a4 .ft { margin-top: 20px; padding-top: 14px; } .a5 .ft { margin-top: 12px; padding-top: 9px; }
        .fu-lbl { text-transform: uppercase; letter-spacing: .04em; color: #9ca3af; }
        .fu-date { font-weight: 700; color: #7a1a2e; }
        .a4 .fu-lbl { font-size: 9px; } .a4 .fu-date { font-size: 13px; margin: 2px 0; }
        .a5 .fu-lbl { font-size: 8px; } .a5 .fu-date { font-size: 11px; margin: 1px 0; }
        .sig-line { border-top: 1px solid #7a1a2e; padding-top: 3px; text-align: right; }
        .sig-n { font-weight: 600; color: #1a1a1a; }
        .sig-r { color: #6b7280; }
        .a4 .sig-line { width: 165px; margin-left: auto; } .a4 .sig-n { font-size: 12px; } .a4 .sig-r { font-size: 10px; }
        .a5 .sig-line { width: 115px; margin-left: auto; } .a5 .sig-n { font-size: 10px; } .a5 .sig-r { font-size: 9px; }
        .wm { text-align: center; color: #d0a0a8; border-top: 1px solid #f5e0e4; }
        .a4 .wm { font-size: 9px; margin-top: 10px; padding-top: 6px; } .a5 .wm { font-size: 8px; margin-top: 6px; padding-top: 4px; }

        @media print {
          /* Hide the app sidebar and shell chrome */
          .shell > aside,
          .shell > div > aside,
          .shell nav,
          .shell .sidebar,
          .shell [class*="sidebar"],
          .shell [class*="Sidebar"] { display: none !important; }
          .shell { display: block !important; }
          .shell-main { margin-left: 0 !important; padding: 0 !important; width: 100% !important; }
          .shell-page { padding: 0 !important; margin: 0 !important; max-width: 100% !important; animation: none !important; }

          /* Hide prescription controls */
          .controls, .bar2, .top-bar { display: none !important; }

          /* Clean up the prescription itself */
          body { background: #fff !important; padding: 0 !important; margin: 0 !important; }
          #rx-wrap { margin: 0 !important; }
          .rx { box-shadow: none !important; border: none !important; margin: 0 auto !important; padding-top: 10px !important; }
        }
      `}</style>

      <div className="top-bar">
        <div className={`tab ${lang === 'mr' ? 'active' : ''}`} onClick={() => setLang('mr')}>मराठी</div>
        <div className={`tab ${lang === 'hi' ? 'active' : ''}`} onClick={() => setLang('hi')}>हिंदी</div>
        <div className={`tab ${lang === 'en' ? 'active' : ''}`} onClick={() => setLang('en')}>English</div>
      </div>

      <div className="bar2">
        <button className={`sbtn ${size === 'a4' ? 'active' : ''}`} onClick={() => setSize('a4')}>A4</button>
        <button className={`sbtn ${size === 'a5' ? 'active' : ''}`} onClick={() => setSize('a5')}>A5 (Rx Pad)</button>
        <button className="pbtn" onClick={() => window.print()}>🖨 Print</button>
      </div>

      <div id="rx-wrap">
        <div className={`rx ${size}`}>
          <div className="hd">
            <div className="clinic-row">
              <div className="clinic-title">{d.clinicName}</div>
            </div>
            <div className="doctors-row">
              <div className="doc-l">
                <div className="doc-name">{d.doc1.name}</div>
                <div className="doc-deg">{d.doc1.deg}</div>
                <div className="doc-spec">{d.doc1.spec}</div>
                <div className="doc-meta">{d.doc1.reg}</div>
                <div className="doc-meta">{d.doc1.mob}</div>
              </div>
              <div className="doc-c">
                <div className="logo-wrap">
                  <img src={LOGO} alt="clinic logo" />
                </div>
              </div>
              <div className="doc-r">
                <div className="doc-name">{d.doc2.name}</div>
                <div className="doc-deg">{d.doc2.deg}</div>
                <div className="doc-spec">{d.doc2.spec}</div>
                <div className="doc-meta">{d.doc2.reg}</div>
                <div className="doc-meta">{d.doc2.mob}</div>
              </div>
            </div>
            {isA5 ? (
              <div className="addr-bar" dangerouslySetInnerHTML={{ __html: d.addr }} />
            ) : (
              <div className="addr-bar" dangerouslySetInnerHTML={{ __html: `${d.addr}<br>${d.addr2}` }} />
            )}
          </div>

          <div className="rx-meta">
            <div className="rx-sym">℞</div>
            <div className="rx-date">
              <div>{L.date}: {dynamicData.date}</div>
              <div>{L.visit}: {dynamicData.visitId}</div>
            </div>
          </div>

          <div className="pt-bar">
            <div className="pt-f">
              <label>{L.pname}</label>
              <span>{dynamicData.pt.name}</span>
            </div>
            <div className="pt-f">
              <label>{L.age}</label>
              <span>{dynamicData.pt.age}</span>
            </div>
            <div className="pt-f">
              <label>{L.pid}</label>
              <span>{dynamicData.pt.id}</span>
            </div>
          </div>

          <div className="sec-lbl">{L.meds}</div>
          <table>
            <thead>
              <tr>
                <th style={{ width: 26 }}>{L.no}</th>
                <th>{L.med}</th>
                <th>{L.dose}</th>
                <th>{L.freq}</th>
                <th>{L.dur}</th>
                <th>{L.instr}</th>
              </tr>
            </thead>
            <tbody>
              {dynamicData.meds.length > 0 ? (
                dynamicData.meds.map((m, i) => (
                  <tr key={i}>
                    <td>{i + 1}</td>
                    <td>
                      <div className="mn">{m.n}</div>
                      {m.g && <div className="mg">{m.g}</div>}
                    </td>
                    <td>{m.d}</td>
                    <td>{m.f}</td>
                    <td>{m.dur}</td>
                    <td>{m.i}</td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="6" style={{ textAlign: 'center', padding: '10px 0' }}>{L.empty}</td>
                </tr>
              )}
            </tbody>
          </table>

          <div className="ft">
            <div>
              <div className="fu-lbl">{L.fu}</div>
              <div className="fu-date">{dynamicData.fuDate}</div>
            </div>
            <div className="sig-line">
              <div className="sig-n">{dynamicData.sigName}</div>
              <div className="sig-r">{dynamicData.sigReg}</div>
            </div>
          </div>

          <div className="wm">{L.valid} · {dynamicData.visitId}</div>
        </div>
      </div>
    </div>
  );
}
